function c(t){if(t.length===0)return 0;let n=0;for(let r=0;r<t.length;r+=1)n+=t[r];return n/t.length}function h(t,n){if(t.length===0)return 0;const r=Math.min(1,Math.max(0,n)),e=(t.length-1)*r,o=Math.floor(e),a=Math.ceil(e);return o===a?t[o]:t[o]+(t[a]-t[o])*(e-o)}function i(t){if(t.length===0)return{count:0,avgHz:0,minMs:0,maxMs:0,p50Ms:0,p95Ms:0};const n=Float64Array.from(t).sort(),r=c(t);return{count:t.length,avgHz:r>0?1e3/r:0,minMs:n[0],maxMs:n[n.length-1],p50Ms:h(n,.5),p95Ms:h(n,.95)}}function u(t){if(t.length<8)return 0;const n=c(Array.from(t,e=>Math.hypot(e.x,e.y)));if(n<=0)return 0;let r=0;for(const e of t)r+=Math.abs(Math.hypot(e.x,e.y)-n);return Math.min(100,r/t.length/n*100)}function f(t,n,r){return Math.min(r,Math.max(n,t))}export{u as a,f as c,i as s};
